import time
import random

class SegmentTree:
    """
    Implementation of a Segment Tree for Range Sum Queries and Point Updates.
    """
    def __init__(self, data):
        self.n = len(data)
        self.tree = [0] * (4 * self.n)
        self._build(data, 1, 0, self.n - 1)

    def _build(self, data, node, start, end):
        if start == end:
            self.tree[node] = data[start]
        else:
            mid = (start + end) // 2
            self._build(data, 2 * node, start, mid)
            self._build(data, 2 * node + 1, mid + 1, end)
            self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def update(self, idx, val):
        self._update(1, 0, self.n - 1, idx, val)

    def _update(self, node, start, end, idx, val):
        if start == end:
            self.tree[node] = val
        else:
            mid = (start + end) // 2
            if start <= idx <= mid:
                self._update(2 * node, start, mid, idx, val)
            else:
                self._update(2 * node + 1, mid + 1, end, idx, val)
            self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def query(self, l, r):
        return self._query(1, 0, self.n - 1, l, r)

    def _query(self, node, start, end, l, r):
        if r < start or end < l:
            return 0
        if l <= start and end <= r:
            return self.tree[node]
        mid = (start + end) // 2
        p1 = self._query(2 * node, start, mid, l, r)
        p2 = self._query(2 * node + 1, mid + 1, end, l, r)
        return p1 + p2

def benchmark():
    # Parameters
    N = 100000
    Q = 50000

    # Synthetic Dataset
    initial_array = [random.randint(1, 100) for _ in range(N)]
    # Pre-generate operations to ensure both methods process identical tasks
    ops = []
    for _ in range(Q):
        op_type = random.choice(['update', 'query'])
        if op_type == 'update':
            ops.append(('U', random.randint(0, N-1), random.randint(1, 100)))
        else:
            l = random.randint(0, N-1)
            r = random.randint(l, N-1)
            ops.append(('Q', l, r))

    # --- Naive Strategy ---
    naive_arr = list(initial_array)
    start_time = time.time()
    for op in ops:
        if op[0] == 'U':
            naive_arr[op[1]] = op[2]
        else:
            # Range sum via slicing/summing
            _ = sum(naive_arr[op[1]:op[2]+1])
    naive_duration = time.time() - start_time

    # --- Segment Tree Strategy ---
    st = SegmentTree(initial_array)
    start_time = time.time()
    for op in ops:
        if op[0] == 'U':
            st.update(op[1], op[2])
        else:
            _ = st.query(op[1], op[2])
    st_duration = time.time() - start_time

    print(f"Benchmark Results (N={N}, Q={Q})")
    print(f"----------------------------------")
    print(f"Naive Array Strategy:    {naive_duration:.4f} seconds")
    print(f"Segment Tree Strategy:   {st_duration:.4f} seconds")
    print(f"Speedup Factor:          {naive_duration / st_duration:.2f}x")

if __name__ == "__main__":
    benchmark()
